/* Cambridge B2 First · Test 2 – đề tự biên soạn theo định dạng content/exams/spec/cam-b2.json (7 phần Đọc + Use of English, 2 phần Viết, 4 phần Nghe, 4 phần Nói).
 * Không chép đề/sách. Cấu trúc: docs/specs/cambridge.md · cổng: scripts/content-qa/exam-format-check.mjs (họ cam-b2). Phần Viết đánh số tiếp sau phần Đọc (8 essay, 9 report).
 * Đánh số câu Đọc: P1 1–8, P2 9–16, P3 17–24, P4 25–30, P5 31–36, P6 37–42, P7 43–52. */
(self.CAMBRIDGE = self.CAMBRIDGE || []).push({
  id: "b2-t2", level: "b2", spec: "cam-b2", n: 2,
  title: "B2 First · Test 2",
  rw: { parts: [
    { n: 1, type: "mcq-gap", instr: "For each question, choose the correct answer.", title: "A wilder countryside", text: "Rewilding is an idea that has (1) off in recent years. Instead of managing land to produce food or timber, conservationists step back and let nature (2) over. One farm in the south of England is a good example: the owners decided to (3) up farming altogether, and the land was left to grow wild. Within five years, rare birds had returned, and the river, once straight and almost lifeless, began to (4) its own course again. Not everyone is (5) on the approach, however. Some neighbouring farmers worry that predators will (6) a threat to their sheep, while others complain that the untidy fields look neglected. Supporters reply that the benefits, such as cleaner water and fewer floods, far (7) the risks. They add that the project has created jobs in tourism, which has (8) the local economy a welcome boost.", items: [
      { n: 1, options: ["set", "taken", "gone", "run"], a: 1, cue: "an idea that has … off in recent years", explain: "\"Take off\" means to become suddenly popular, so the form is \"has taken off\". \"Set off\", \"go off\" and \"run off\" have other meanings." },
      { n: 2, options: ["turn", "run", "get", "take"], a: 3, cue: "step back and let nature … over", explain: "\"Take over\" means to gain control. \"Turn over\", \"run over\" and \"get over\" do not fit this meaning." },
      { n: 3, options: ["take", "put", "give", "hold"], a: 2, cue: "the owners decided to … up farming altogether", explain: "\"Give up\" means to stop doing something. \"Take up\" means to start, which is the opposite." },
      { n: 4, options: ["trace", "pursue", "follow", "track"], a: 2, cue: "began to … its own course again", explain: "A river \"follows its course\". The other verbs are not used with \"course\" in this way." },
      { n: 5, options: ["keen", "fond", "eager", "glad"], a: 0, cue: "Not everyone is … on the approach", explain: "\"Keen on\" is a fixed phrase. \"Fond\", \"eager\" and \"glad\" take other prepositions (of, for, about)." },
      { n: 6, options: ["make", "pose", "give", "cause"], a: 1, cue: "predators will … a threat to their sheep", explain: "The collocation is \"pose a threat\". We do not say \"make\", \"give\" or \"cause\" a threat." },
      { n: 7, options: ["overlook", "overcome", "overtake", "outweigh"], a: 3, cue: "fewer floods far … the risks", explain: "\"Outweigh\" means to be greater in importance. \"Overcome\" means to defeat and \"overlook\" means to fail to notice." },
      { n: 8, options: ["given", "made", "put", "taken"], a: 0, cue: "has … the local economy a welcome boost", explain: "\"Give something a boost\" is the fixed phrase, and \"has given\" is the present perfect. \"Made\" and \"put\" do not take this pattern." },
    ] },
    { n: 2, type: "open-gap", instr: "For each question, write the correct answer. Use only ONE word in each gap.", title: "Ten minutes a day", text: "When Marta downloaded a language-learning app last spring, she never expected it (9) change her daily routine. At first, she only used it (10) her way to work, but the short lessons were so enjoyable that she soon found herself practising during lunch breaks (11) well. \"I used to think that learning a language was something that could only (12) done in a classroom,\" she says. \"Now I know (13) is possible to make real progress in just ten minutes a day.\" Of course, an app is no substitute (14) conversation with real people, and Marta admits she was too shy to speak at first. However, after a few weeks she joined an online chat group, (15) is where her confidence really grew. \"If I (16) not started with the app, I would never have dared to talk to anyone,\" she laughs.", items: [
      { n: 9, a: ["to"], cue: "she never expected it … change her daily routine", explain: "\"Expect something to happen\": the verb \"expect\" is followed by a to-infinitive." },
      { n: 10, a: ["on"], cue: "she only used it … her way to work", explain: "The fixed phrase is \"on her way to work\"." },
      { n: 11, a: ["as"], cue: "practising during lunch breaks", explain: "\"As well\" means \"too\" and comes at the end of the clause." },
      { n: 12, a: ["be"], cue: "something that could only … done in a classroom", explain: "A passive with a modal needs \"be\" plus a past participle: \"could only be done\"." },
      { n: 13, a: ["it"], cue: "Now I know … is possible to make real progress", explain: "\"It\" is the empty subject: \"it is possible to …\"." },
      { n: 14, a: ["for"], cue: "is no substitute … conversation with real people", explain: "\"A substitute for\" something is the fixed pattern." },
      { n: 15, a: ["which"], cue: "joined an online chat group", explain: "A non-defining relative clause about the whole group needs \"which\": \"…, which is where her confidence grew\"." },
      { n: 16, a: ["had"], cue: "If I … not started with the app", explain: "The third conditional needs \"had\" plus a past participle in the if-clause: \"If I had not started …\"." },
    ] },
    { n: 3, type: "word-formation", instr: "For each question, write the correct answer. Use the word given in capitals at the end of some of the lines to form a word that fits in the gap in the same line.", title: "Life in the lookout tower", text: "Being a fire lookout is not a job for everyone. Each summer, Dana Reyes climbs a tower in the mountains and spends five months watching the forest for smoke. The (17) of the work surprises most visitors: for hours at a time nothing happens, yet she must stay (18) at all times. \"People imagine it is lonely, but I have a great (19) of wildlife to keep me company,\" she says. Her tower has no electricity, so careful (20) is vital, from rationing food to charging her radio. Every morning she records the (21) of the wind and the temperature. When she spots smoke, she must call the fire crew at once, because in an (22) every minute counts. Her early warnings have saved several villages, and she feels a deep sense of (23). Even so, she admits that the job would be (24) for anyone who hates silence.", items: [
      { n: 17, text: "(17) ___ (REPEAT)", a: ["repetition", "repetitiveness"], cue: "of the work surprises most visitors", explain: "A noun is needed after \"The\": repeat gives \"repetition\". The adjective \"repetitive\" does not fit after \"The\"." },
      { n: 18, text: "(18) ___ (ATTENTION)", a: ["attentive"], cue: "yet she must stay", explain: "After \"stay\" we need an adjective: \"attentive\". The noun \"attention\" would not fit." },
      { n: 19, text: "(19) ___ (VARY)", a: ["variety"], cue: "I have a great … of wildlife to keep me company", explain: "\"A great variety of\" is a fixed phrase and needs a noun." },
      { n: 20, text: "(20) ___ (PLAN)", a: ["planning"], cue: "so careful … is vital", explain: "A noun follows the adjective \"careful\", and \"planning\" is uncountable here. \"Plan\" would need \"a\"." },
      { n: 21, text: "(21) ___ (DIRECT)", a: ["direction"], cue: "she records the … of the wind and the temperature", explain: "A noun is needed after \"the\": the \"direction\" of the wind." },
      { n: 22, text: "(22) ___ (EMERGE)", a: ["emergency"], cue: "because in an … every minute counts", explain: "\"In an emergency\" is the fixed phrase. \"Emergence\" means something starting to appear, which is not the meaning here." },
      { n: 23, text: "(23) ___ (ACHIEVE)", a: ["achievement"], cue: "she feels a deep sense of", explain: "\"A sense of achievement\" needs a noun after \"of\"." },
      { n: 24, text: "(24) ___ (SUIT)", a: ["unsuitable"], cue: "the job would be … for anyone who hates silence", explain: "The meaning is negative (not good for people who hate silence), so we need \"unsuitable\", not \"suitable\"." },
    ] },
    { n: 4, type: "transformation", instr: "For each question, complete the second sentence so that it has a similar meaning to the first sentence, using the word given. Do not change the word given. You must use between two and five words, including the word given.", items: [
      { n: 25, text: "\"I'll phone you as soon as I get there,\" Jo told her mother.\nKEY WORD: PROMISED\nJo ___ her mother as soon as she got there.", a: ["promised to phone", "promised to call", "promised to ring", "promised to telephone"], cue: "I'll phone you as soon as I get there", explain: "\"Promise\" is followed by a to-infinitive. The reported sentence needs the past tense \"promised\"." },
      { n: 26, text: "I last saw Maria two years ago.\nKEY WORD: SEEN\nI ___ Maria for two years.", a: ["haven't seen", "have not seen"], cue: "I last saw Maria two years ago", explain: "\"For two years\" needs the present perfect: \"haven't seen\". The simple past does not go with \"for\" here." },
      { n: 27, text: "Unless you hurry, you'll miss the last bus.\nKEY WORD: IF\nYou'll miss the last bus ___ hurry.", a: ["if you don't", "if you do not"], cue: "Unless you hurry, you'll miss the last bus", explain: "\"Unless\" means \"if … not\", so we need \"if you don't\" before \"hurry\"." },
      { n: 28, text: "Someone has stolen my bike from outside the library.\nKEY WORD: BEEN\nMy bike ___ from outside the library.", a: ["has been stolen", "has just been stolen", "has been taken"], cue: "Someone has stolen my bike from outside the library", explain: "The active present perfect becomes a passive present perfect: \"has been stolen\"." },
      { n: 29, text: "Ice-swimming is not as easy as it looks.\nKEY WORD: MORE\nIce-swimming ___ it looks.", a: ["is more difficult than", "is more challenging than", "is more demanding than", "is much more difficult than"], cue: "Ice-swimming is not as easy as it looks", explain: "\"Not as easy as\" means \"more difficult than\", and the key word needs \"more\" plus a longer adjective." },
      { n: 30, text: "I regret not taking the job in Madrid.\nKEY WORD: WISH\nI ___ the job in Madrid.", a: ["wish I had taken", "wish I'd taken"], cue: "I regret not taking the job in Madrid", explain: "Regret about the past is expressed with \"wish\" plus the past perfect: \"wish I had taken\"." },
    ] },
    { n: 5, type: "mcq", instr: "For each question, choose the correct answer.", title: "Less is more? A year of owning almost nothing", by: "A writer describes an experiment in minimalism.", text: [
      "Last January, I sold my sofa. It was an impulsive decision, made after a friend visited, glanced around my flat and asked, quite innocently, why I owned so many things I never used. I had no good answer. Over the next twelve months, I got rid of nearly two thirds of what I owned, from kitchen gadgets to shelves of books I would never reread. I wasn't aiming to become a monk. I simply wanted to find out whether all this stuff was making my life better or only making my cupboards fuller.",
      "The first few weeks were exhilarating. Every bag I carried to the charity shop felt like a small victory, and my flat suddenly seemed twice the size. But I soon discovered that getting rid of objects is easy compared with getting rid of the feelings attached to them. A scruffy jacket my father used to wear took me three attempts to part with, and I still wonder whether I did the right thing. I learnt to ask a different question: not \"might I need this?\" but \"does this add anything today?\"",
      "What surprised me most was the effect on my spending. Without a pile of unopened parcels, I realised how much of my shopping had been a reaction to boredom rather than need. Now I wait thirty days before buying anything that is not food, and in most cases the urge simply disappears. By the summer, I was saving almost a third of my salary, which I hadn't managed in my whole adult life.",
      "Not everything went smoothly, though. Friends were divided: some found my empty shelves inspiring, while others quietly worried that I was depressed. My sister, who has three children and a house full of toys, found the whole experiment faintly insulting, as if I were criticising how she lived. I understood her point. Minimalism can easily turn into a kind of showing off, a competition about who owns the least, and that is as shallow as the consumerism it claims to reject.",
      "I also made mistakes. In March I threw away a perfectly good printer, and in June I needed it for a form that had to be posted. The new one cost me more than the old one had. Experts say this happens to most beginners, who clear things out too quickly and then buy them back. The sensible approach, they suggest, is to put doubtful items in a box, seal it, and see whether you open it within three months.",
      "A year on, I still don't own a sofa, but I do own a very comfortable armchair, and I have no plans to fill the empty corner. What I have gained isn't tidiness so much as attention. I notice what I use, what I enjoy, and what I am only keeping out of habit. I wouldn't recommend my method to everyone, but I would recommend the question my friend asked. It cost me a sofa, and it was worth every penny.",
    ], items: [
      { n: 31, q: "What led the writer to sell the sofa?", options: ["The flat had become too small for it.", "The writer needed some extra money.", "A friend's question made the writer reflect.", "The sofa had become uncomfortable."], a: 2, cue: "why I owned so many things I never used", explain: "A visiting friend asked why the writer owned so many unused things, and that prompted the decision. Money and space are not mentioned." },
      { n: 32, q: "What did the writer find harder than expected?", options: ["Parting with things that carried memories.", "Finding a charity shop that would accept things.", "Carrying heavy bags to the shop.", "Deciding which books to keep."], a: 0, cue: "getting rid of the feelings attached to them", explain: "The writer says that removing the feelings attached to objects is harder than removing the objects, as the jacket example shows. Books are mentioned only as something easy to give away." },
      { n: 33, q: "What does the writer say about spending?", options: ["The writer was earning more than before.", "Most of the shopping had been for essential items.", "Waiting before buying usually led to a better choice.", "Much earlier shopping had been a response to boredom."], a: 3, cue: "a reaction to boredom rather than need", explain: "The writer realised that shopping had been \"a reaction to boredom rather than need\". The salary did not rise; the writer simply saved more." },
      { n: 34, q: "Why did the writer's sister react badly to the experiment?", options: ["She was concerned that the writer was unhappy.", "She felt it suggested that her own way of life was wrong.", "She had already tried to own less herself.", "She refused to visit the writer's flat."], a: 1, cue: "as if I were criticising how she lived", explain: "She found the experiment \"faintly insulting\", as if the writer were criticising her life. It was other friends, not the sister, who feared depression." },
      { n: 35, q: "What advice do experts give to beginners?", options: ["Keep uncertain items in a sealed box for some time.", "Clear out one room at a time.", "Ask a friend to help decide.", "Replace old things with better ones."], a: 0, cue: "put doubtful items in a box, seal it", explain: "Beginners should put doubtful items in a sealed box and see whether they open it within three months. Rooms and friends are not mentioned." },
      { n: 36, q: "What is the writer's attitude at the end of the article?", options: ["regret about the whole experiment", "a wish to own nothing in the future", "approval of paying attention to what matters, but not of the method for all", "an intention to fill the empty corner soon"], a: 2, cue: "I wouldn't recommend my method to everyone", explain: "The writer values the habit of noticing what matters, but does not urge everyone to copy the method. The empty corner will stay empty." },
    ] },
    { n: 6, type: "gapped-text", instr: "You are going to read an article about ice-swimming. Six sentences have been removed from the article. Choose from the sentences A–G the one which fits each gap (37–42). There is one extra sentence which you do not need to use.", title: "Into the cold", by: "Hana Mills writes about taking up ice-swimming.", text: [
      "I never planned to become an ice-swimmer. Two winters ago, a colleague invited me to her local lake at seven o'clock on a freezing Sunday morning, and I said yes mainly because I was too embarrassed to refuse. (37) By the time I reached the lake, I was seriously thinking of pretending I had a stomach ache. A dozen people were already on the wooden jetty, laughing and drinking tea in swimming costumes and woolly hats.",
      "The group's leader, a retired nurse called Pauline, gave me a short talk before I went in. (38) \"Nobody here is trying to be a hero,\" she said. \"Walk in slowly, breathe out, and get out when your body tells you to.\" I lasted ninety seconds that first morning, and for the first thirty of them I could think of nothing except the pain in my feet.",
      "Climbing back onto the jetty, I was shivering uncontrollably. (39) My skin was bright pink, and my hands shook so much that I could not undo my buttons, yet I felt wonderfully awake, as if somebody had switched a light on inside me.",
      "I expected the experience to be a one-off, but I was back the following Sunday. (40) Everyone had a flask, a story and a piece of advice, and within a month I knew most of the regulars by name. Pauline even knitted me a hat.",
      "Scientists have only recently begun to study why cold-water swimming makes people feel so good. (41) A few small studies suggest that the cold may reduce stress, although the evidence is still limited. Doctors are more cautious, and they advise anyone with heart problems to ask for medical advice first.",
      "These days I swim three mornings a week, even in January, when we sometimes have to break the ice with a stick. (42) I no longer do it to prove anything. I do it because those ninety seconds in the water make everything else in the day seem easier.",
    ], options: [
      "A Her main message was that safety matters far more than pride.",
      "B People often ask me whether I am mad, and I understand why.",
      "C Nothing, however, had prepared me for what happened next.",
      "D The lake itself was formed by a glacier thousands of years ago.",
      "E I hardly slept the night before, imagining the water.",
      "F What I had not expected was how friendly everyone would be.",
      "G The honest answer, so far, is that nobody is certain.",
    ], items: [
      { n: 37, text: "Gap 37", a: "E", cue: "too embarrassed to refuse", explain: "The writer's worry builds up before the trip, and the next sentence continues the anxiety (\"By the time I reached the lake\"). Sentence D is about the lake's history and does not fit." },
      { n: 38, text: "Gap 38", a: "A", cue: "gave me a short talk before I went in", explain: "Pauline's talk is summarised in A, and her quotation (\"Nobody here is trying to be a hero\") then explains it." },
      { n: 39, text: "Gap 39", a: "C", cue: "I was shivering uncontrollably", explain: "\"Nothing, however, had prepared me\" introduces the surprise described next: feeling wonderfully awake after being so cold." },
      { n: 40, text: "Gap 40", a: "F", cue: "I was back the following Sunday", explain: "The next sentence describes everyone's friendliness (flask, story, advice), so F introduces it." },
      { n: 41, text: "Gap 41", a: "G", cue: "why cold-water swimming makes people feel so good", explain: "The sentence before asks why swimming feels good, G answers \"nobody is certain\", and the next sentence gives the limited evidence." },
      { n: 42, text: "Gap 42", a: "B", cue: "to break the ice with a stick", explain: "The writer swims even in freezing conditions, so people ask if the writer is mad. \"I no longer do it to prove anything\" answers that." },
    ] },
    { n: 7, type: "matching", instr: "You are going to read four short texts in which people describe their jobs on a film set. For each question, choose from the people (A–D). The people may be chosen more than once.", texts: [
      { code: "A", title: "Imogen, location manager", text: "When I tell people what I do, they imagine me strolling through castles and beaches, choosing the most beautiful backdrop for the director. In reality, about seventy per cent of my week is spent on permits, insurance forms and maps of car parks. I had no idea the job would be so much about paperwork when I applied. The creative part is brief, but it's what I love: spotting a derelict factory or a quiet lane and seeing a story in it. The tricky part comes afterwards. A film crew of eighty people arriving in a small street at six in the morning is not a welcome sight, so I knock on every door in advance, explain what will happen and offer a small payment for the trouble. Most people agree, and some even enjoy it, but there is always one person who objects to the lights or the parked lorries. My rule is simple: leave every place tidier than you found it, and you will be invited back." },
      { code: "B", title: "Joel, costume assistant", text: "I started in this job by accident. I was helping a friend move boxes at a theatre, someone was ill that day, and I ended up holding a needle. Three years later I'm still here. Most people think costumes are about beautiful dresses, but a large part of my work is making brand-new clothes look as if somebody has lived in them for years. I rub dirt into jackets, cut holes in trousers and wash shirts until they are soft and faded. If a character is supposed to be poor, nothing must look fresh from a shop. It's a strange kind of art, because I spend days making things look worse. I'm normally the first person on set, because every actor needs dressing before the cameras start, and I'm usually the last to leave, since someone has to wash, repair and count everything for the next day. It's tiring, but there's a special pleasure in seeing a character come alive in a coat I spent two days ruining." },
      { code: "C", title: "Nasrin, stunt performer", text: "People assume you have to be fearless, and I can honestly say I'm not. Before a big fall or a car scene, my hands go cold and my stomach turns over. What I've learnt over twelve years is not to fight the feeling. I take a few slow breaths, go through every step of the plan in my head, and tell myself that the fear is simply my body getting ready. By the time the director calls action, I'm calm. Everything is rehearsed, of course; we use ramps, padding and safety wires, and a stunt that looks wild on screen has usually been practised thirty times. Still, accidents happen. Two years ago I broke my back during a fight scene, and the doctors told me I might never work again. I spent nine months in rehabilitation, and I went back to set last spring, a little more careful but just as keen. Honestly, I can't imagine doing anything else." },
      { code: "D", title: "Tomas, sound recordist", text: "Half of my job is waiting. We might be ready to film a quiet scene in a country garden, and then a plane flies overhead, or a neighbour starts a lawnmower, and everybody has to stand still until the noise has gone. Some days we lose an entire hour that way. Nobody on a film set likes being kept waiting, but I've learnt to take it calmly; shouting never makes a plane fly faster. People rarely think about sound at all. Audiences only become aware of it when something is wrong: if the dialogue is muffled, or a microphone appears at the top of the picture, they complain, but a perfect recording goes completely unnoticed. I've accepted that. The strange side effect of spending all day in headphones is that I now hear everything: the hum of a fridge, the squeak of a bus door, the birds outside my window at dawn. I can't switch it off, even on holiday." },
    ], items: [
      { n: 43, text: "has found a way to stay calm when facing a risky task", a: "C", cue: "I take a few slow breaths", explain: "Nasrin controls her fear with slow breathing and mental rehearsal. The other speakers do not mention fear." },
      { n: 44, text: "has to persuade local people to put up with disturbance", a: "A", cue: "I knock on every door in advance", explain: "Imogen visits residents beforehand to explain the filming and to offer a payment." },
      { n: 45, text: "spends much of the working day waiting for the right conditions", a: "D", cue: "Half of my job is waiting", explain: "Tomas waits for planes and lawnmowers to stop making noise." },
      { n: 46, text: "makes new objects appear old and used", a: "B", cue: "making brand-new clothes look as if somebody has lived in them", explain: "Joel adds dirt, holes and fading to new clothes so that they look worn." },
      { n: 47, text: "knows that the audience only notices the work when there is a problem", a: "D", cue: "Audiences only become aware of it when something is wrong", explain: "Tomas says people think about sound only when the recording is bad." },
      { n: 48, text: "is on set before everyone else and still there after they leave", a: "B", cue: "I'm normally the first person on set", explain: "Joel is first to arrive and usually the last to leave." },
      { n: 49, text: "returned to work after a serious injury", a: "C", cue: "I broke my back during a fight scene", explain: "Nasrin spent nine months recovering and went back to set." },
      { n: 50, text: "did not realise how much of the job would be administration", a: "A", cue: "I had no idea the job would be so much about paperwork", explain: "Imogen expected travelling and creative work, but most of her week is spent on forms and permits." },
      { n: 51, text: "got into the job by chance", a: "B", cue: "I started in this job by accident", explain: "Joel began when he helped a friend and someone was ill." },
      { n: 52, text: "has become more aware of everyday sounds outside work", a: "D", cue: "I now hear everything", explain: "Tomas's daily headphone use means that he notices the hum of a fridge and a bus door, even on holiday." },
    ] },
    { n: 8, type: "essay", min_words: 140, minutes_hint: 40, prompt: "In your English class you have been talking about language learning. Now your teacher has asked you to write an essay. Write an essay using ALL the notes and give reasons for your point of view. Essay question: Are language-learning apps better than classes? Notes. Write about: 1. flexibility, 2. motivation, 3. (your own idea). Write your essay in 140–190 words.", points: ["discuss flexibility (when and where people can study)", "discuss motivation", "add an idea of your own"], checks: [["flexib", "timetable", "own pace", "any time", "schedule"], ["motivat", "encourag", "streak", "keen", "give up"], ["speaking", "conversation", "cost", "cheap", "native speaker"]], model: "Language-learning apps have become hugely popular, but are they really better than classes? In my view, they are a very useful tool, although they cannot completely replace a teacher.\nThe main advantage of an app is flexibility. Learners can study on the bus, at lunchtime or late at night, at their own pace, whereas a class has a fixed timetable that is difficult to combine with work or family life. As a result, busy people are more likely to practise every day.\nMotivation is another important point. Apps encourage users with points, short lessons and daily streaks, so many people feel keen to continue. However, nobody checks your progress, and it is easy to give up after a few weeks. In a class, the teacher and the other students keep you going.\nIn addition, speaking practice is the weakest side of apps. A machine cannot replace real conversation, for example when you need to ask why an answer is wrong.\nTo sum up, the best solution is a mixture of both: an app for daily habits and a class for conversation.", tips: ["Use all three notes and give a reason for each.", "Write four paragraphs: introduction, two note paragraphs, conclusion.", "Use linkers: however, whereas, as a result, in addition, although.", "Keep a neutral, formal register and 140–190 words."] },
    { n: 9, type: "report", min_words: 140, minutes_hint: 40, prompt: "Your town council is thinking of opening a community fridge, where shops and neighbours leave spare food for anyone to take for free. You have been asked to write a report for the council. In your report, say who would use it, suggest where it could be placed, and explain what problems might arise and how to solve them. Write your report in 140–190 words.", points: ["say who would use the fridge", "suggest where to place it", "explain problems and make recommendations"], checks: [["famil", "student", "elderly", "residents", "low incomes"], ["library", "market", "location", "placed", "situated"], ["problem", "risk", "hygiene", "recommend", "suggest"]], model: "Introduction\nThe purpose of this report is to explain how a community fridge could help people in our town and to recommend how the council should set one up.\nWho would use it\nA community fridge lets shops and neighbours share spare food for free. Families on low incomes, students and elderly residents would benefit most, whereas local cafés would be able to give away food that would otherwise be thrown away. As a result, less food would be wasted.\nLocation\nThe best place would be the town library, because it is central, warm and open six days a week. Another option is the market square, although the weather could cause problems there.\nProblems and recommendations\nThe main risks are hygiene and untidiness. Therefore, I recommend that trained volunteers should check the fridge daily, remove old food and keep a simple cleaning rota. In addition, clear signs should explain the rules.\nConclusion\nDespite these difficulties, a community fridge is a cheap and practical way to support residents, so I strongly suggest that the council goes ahead with a six-month trial.", tips: ["Use clear headings: Introduction, then one for each point, then Conclusion.", "Cover all three points and make at least one clear recommendation.", "Use a neutral, formal style: I recommend that…, It would be…, Therefore…", "Write 140–190 words and keep each section short."] },
  ] },
  listening: { parts: [
    { n: 1, type: "mcq", instr: "For each question, choose the correct answer. You will hear each recording twice.", units: [
      { speakers: { A: { name: "Alison", accent: "en-GB", gender: "f" } }, script: [{ say: "One. You hear a woman leaving a voicemail message. Why can't Alison come on Thursday?" }, { s: "A", t: "Hi Greg, it's Alison. I'm afraid I can't make Thursday's rehearsal after all. My train company has cancelled the evening service, and I won't get back in time. I can do Saturday morning if that suits everyone." }], items: [{ n: 1, q: "Why can't Alison come on Thursday?", options: ["She has another appointment.", "Her transport is not running.", "She is feeling unwell."], a: 1, cue: "has cancelled the evening service", explain: "Her train company has cancelled the evening service, so she cannot get back. She does not mention an appointment or illness." }] },
      { speakers: { M: { name: "Man", accent: "en-GB", gender: "m" }, W: { name: "Woman", accent: "en-GB", gender: "f" } }, script: [{ say: "Two. You hear two friends talking about a restaurant. What was the man's problem?" }, { s: "M", t: "I wouldn't go back there. The food was fine, but we waited forty minutes just to order." }, { s: "W", t: "Really? I thought the staff were so friendly." }, { s: "M", t: "They were, which is why I'm not complaining more." }], items: [{ n: 2, q: "What was the man's problem with the restaurant?", options: ["the slow service", "the price of the meal", "the quality of the food"], a: 0, cue: "we waited forty minutes just to order", explain: "The man waited forty minutes just to order. He says the food was fine, and he does not mention the price." }] },
      { speakers: { R: { name: "Presenter", accent: "en-GB", gender: "m" } }, script: [{ say: "Three. You hear a radio presenter talking about some research. What do the researchers want to find out next?" }, { s: "R", t: "Scientists at the university have found that people who walk in woods for just twenty minutes show lower stress levels than those who walk along city streets. The team now hopes to find out whether the effect lasts a whole day." }], items: [{ n: 3, q: "What do the researchers want to find out next?", options: ["whether longer walks help more", "whether city parks work as well", "whether the effect lasts all day"], a: 2, cue: "whether the effect lasts a whole day", explain: "The team hopes to find out whether the effect lasts a whole day. The length of the walk and the type of park are not discussed." }] },
      { speakers: { W: { name: "Woman", accent: "en-GB", gender: "f" }, M: { name: "Man", accent: "en-GB", gender: "m" } }, script: [{ say: "Four. You hear two friends talking about a new job. What does the man like most about it?" }, { s: "W", t: "How's the new job?" }, { s: "M", t: "Better than I expected, honestly. The pay isn't amazing, but my manager lets me work from home on Fridays, and that makes a huge difference." }], items: [{ n: 4, q: "What does the man like most about his job?", options: ["the chance to work from home", "the money he earns", "the location of the office"], a: 0, cue: "lets me work from home on Fridays", explain: "He says the pay is not amazing, but working from home on Fridays makes a huge difference." }] },
      { speakers: { C: { name: "Courier", accent: "en-GB", gender: "m" } }, script: [{ say: "Five. You hear a man talking about his job. What does he find most difficult?" }, { s: "C", t: "I've been a bike courier for six years. People think the danger is traffic, and of course that matters, but the thing that really wears you down is the weather. Riding in freezing rain for ten hours is miserable, and no jacket completely solves it." }], items: [{ n: 5, q: "What does the courier find most difficult?", options: ["heavy traffic", "carrying heavy loads", "spending hours in bad weather"], a: 2, cue: "freezing rain for ten hours", explain: "Traffic matters, but \"the thing that really wears you down is the weather\", such as riding for ten hours in freezing rain." }] },
      { speakers: { G: { name: "Guide", accent: "en-GB", gender: "f" } }, script: [{ say: "Six. You hear an announcement at a museum. What can visitors do today?" }, { s: "G", t: "Welcome to the maritime museum. Please note that the ship model gallery on the second floor is closed for cleaning today, but the film about the Arctic voyage will be shown every hour in the main hall, and it's included in your ticket." }], items: [{ n: 6, q: "What can visitors do today?", options: ["see a film at no extra cost", "visit the ship model gallery", "join a guided tour"], a: 0, cue: "included in your ticket", explain: "The film is shown every hour and is included in the ticket. The model gallery is closed, and no tour is mentioned." }] },
      { speakers: { T: { name: "Tutor", accent: "en-GB", gender: "f" }, B: { name: "Ben", accent: "en-GB", gender: "m" } }, script: [{ say: "Seven. You hear a tutor talking to a student about an essay. What is the tutor's criticism?" }, { s: "T", t: "Your essay has strong ideas, Ben, but the conclusion is rushed. You've clearly run out of time." }, { s: "B", t: "I spent too long on the introduction, I think." }, { s: "T", t: "Then next time, plan your time more carefully." }], items: [{ n: 7, q: "What is the tutor's criticism of the essay?", options: ["The ideas are weak.", "The ending is too hurried.", "The essay is too long."], a: 1, cue: "the conclusion is rushed", explain: "The tutor praises the ideas and says the conclusion is rushed because Ben ran out of time." }] },
      { speakers: { W: { name: "Woman", accent: "en-GB", gender: "f" } }, script: [{ say: "Eight. You hear a woman talking about moving to the countryside. What does she miss about city life?" }, { s: "W", t: "I thought I'd miss the city, but what I actually miss is the choice. Here, if I want a particular kind of bread, I have to drive twenty minutes. On the other hand, I now know all my neighbours, which never happened in the flat." }], items: [{ n: 8, q: "What does she miss about city life?", options: ["good public transport", "knowing her neighbours", "having plenty of choice"], a: 2, cue: "what I actually miss is the choice", explain: "She misses the choice of shops. She knows her neighbours better now, and transport is not mentioned." }] },
    ] },
    { n: 2, type: "sentence", instr: "You will hear a woman called Rosa Kerr giving an introductory talk about a beekeeping course. For each question, write the missing word or number in the gap. You will hear the recording twice.", units: [
      { title: "Hillside Beekeeping Course", speakers: { R: { name: "Rosa", accent: "en-GB", gender: "f" } }, script: [
        { say: "Part Two. You will hear a woman called Rosa Kerr giving an introductory talk about a beekeeping course." },
        { s: "R", t: "Hello everyone, and welcome to the Hillside Beekeeping Course. My name is Rosa Kerr, and I've kept bees for over twenty years. Let me tell you what to expect over the next ten weeks." },
        { s: "R", t: "We meet every Wednesday evening, starting at seven o'clock, in the old schoolhouse beside the village church. The course costs one hundred and forty pounds, and that includes all your equipment except a protective suit, which most people prefer to buy themselves." },
        { s: "R", t: "In the first month, we'll be learning about the life of the colony: how the queen, the workers and the drones each have a different role. From week five onwards, we move outdoors to the apiary, which is on a hill about a mile from here." },
        { s: "R", t: "Please wear light-coloured clothing, because bees get nervous around dark colours. And one thing I always tell beginners: never wear perfume, as the scent can attract them." },
        { s: "R", t: "Many people ask how much honey they can expect. A healthy hive can produce around twenty kilograms a year, though in a wet summer it's often much less. Finally, you'll need to register your hives with the local authority, and I'll help with the forms." },
      ], items: [
        { n: 9, text: "The course meets every ___ evening.", a: ["Wednesday", "Wednesdays"], cue: "every Wednesday evening", explain: "Rosa says the group meets \"every Wednesday evening\"." },
        { n: 10, text: "Each session starts at ___ o'clock.", a: ["7", "seven", "7.00", "7:00", "7pm", "7 pm"], cue: "starting at seven o'clock", explain: "Sessions start at seven o'clock." },
        { n: 11, text: "The meetings take place in the old ___ near the church.", a: ["schoolhouse", "school house"], cue: "the old schoolhouse beside the village church", explain: "The venue is the old schoolhouse beside the village church." },
        { n: 12, text: "The course costs £___.", a: ["140", "£140", "one hundred and forty", "a hundred and forty"], cue: "costs one hundred and forty pounds", explain: "The price is one hundred and forty pounds." },
        { n: 13, text: "Students have to buy their own protective ___.", a: ["suit", "suits"], cue: "except a protective suit", explain: "Equipment is included, except a protective suit." },
        { n: 14, text: "The colony has a queen, workers and ___.", a: ["drones", "drone"], cue: "the queen, the workers and the drones", explain: "The three roles are the queen, the workers and the drones." },
        { n: 15, text: "Outdoor lessons begin in week ___.", a: ["5", "five"], cue: "From week five onwards", explain: "From week five onwards the group moves outdoors." },
        { n: 16, text: "The apiary is on a ___ about a mile away.", a: ["hill", "hillside"], cue: "the apiary, which is on a hill", explain: "The apiary is on a hill about a mile from the schoolhouse." },
        { n: 17, text: "Beginners should never wear ___ near bees.", a: ["perfume"], cue: "never wear perfume", explain: "Perfume can attract the bees." },
        { n: 18, text: "A healthy hive can produce about ___ kilograms of honey a year.", a: ["20", "twenty"], cue: "around twenty kilograms a year", explain: "A healthy hive can produce around twenty kilograms a year." },
      ] },
    ] },
    { n: 3, type: "matching", instr: "You will hear five different people talking about moving to a new city. For each speaker (19–23), choose from the list (A–H) what surprised or troubled them most. Use the letters only once. There are three extra letters which you do not need to use. You will hear the recording twice.", options: ["A the cost of housing", "B the friendliness of strangers", "C finding a job", "D the weather", "E the noise", "F the length of the journey to work", "G feeling lonely", "H the amount of green space"],
      units: [
        { speakers: { P: { name: "Presenter", accent: "en-GB", gender: "m" }, S1: { name: "Speaker 1", accent: "en-GB", gender: "f" }, S2: { name: "Speaker 2", accent: "en-GB", gender: "m" }, S3: { name: "Speaker 3", accent: "en-GB", gender: "f" }, S4: { name: "Speaker 4", accent: "en-GB", gender: "m" }, S5: { name: "Speaker 5", accent: "en-GB", gender: "f" } },
          script: [
            { say: "Part Three. You will hear five different people talking about moving to a new city. What surprised or troubled each of them most?" },
            { say: "Speaker one." },
            { s: "S1", t: "Everyone warned me that rents would be high, and they were, but I'd budgeted for that. What I hadn't expected was how many people spoke to me on the street. In my old town you never said a word to strangers, and here a woman helped me carry my shopping on my first day." },
            { say: "Speaker two." },
            { s: "S2", t: "I'd imagined parks as small squares, but this city is full of gardens and woods. I often cycle through them to work, which takes twenty minutes, so the journey is no problem. My real difficulty is the weeks of grey rain. I wasn't prepared for that." },
            { say: "Speaker three." },
            { s: "S3", t: "My flat is lovely, and the neighbours are kind, but in the first months I hardly spoke to anyone after work. I'd lived with three friends before, so the silence in the evenings was hard. I solved it by joining a choir." },
            { say: "Speaker four." },
            { s: "S4", t: "I thought a bigger city would mean more opportunities, but the job market was harder than I'd imagined. I sent sixty applications before anyone replied. It's different now, and I love my work, but those months nearly made me go home." },
            { say: "Speaker five." },
            { s: "S5", t: "I live above a pub, so it was loud at night at first, but I use earplugs and don't mind. The thing I found surprising was the trains: my commute is an hour and a half each way, and they're often late." },
          ],
          items: [
            { n: 19, text: "Speaker 1", a: "B", cue: "how many people spoke to me on the street", explain: "Rents were expected, but the surprise was how many strangers spoke to her." },
            { n: 20, text: "Speaker 2", a: "D", cue: "the weeks of grey rain", explain: "The parks are a pleasant surprise and the journey is easy. His real difficulty is the rainy weather." },
            { n: 21, text: "Speaker 3", a: "G", cue: "I hardly spoke to anyone after work", explain: "Her neighbours are kind, but she felt lonely in the evenings until she joined a choir." },
            { n: 22, text: "Speaker 4", a: "C", cue: "the job market was harder than I'd imagined", explain: "He had to send sixty applications before anyone replied." },
            { n: 23, text: "Speaker 5", a: "F", cue: "my commute is an hour and a half each way", explain: "The noise does not bother her. The long, unreliable train journey is the surprise." },
          ] },
      ] },
    { n: 4, type: "mcq", instr: "You will hear an interview with a woman called Carla Mendes, who runs a repair café. For each question, choose the correct answer. You will hear the recording twice.", units: [
      { title: "Interview with Carla Mendes", speakers: { P: { name: "Presenter", accent: "en-GB", gender: "m" }, C: { name: "Carla", accent: "en-GB", gender: "f" } }, script: [
        { say: "Part Four. You will hear an interview with a woman called Carla Mendes, who runs a repair café." },
        { s: "P", t: "My guest today is Carla Mendes, who runs a repair café in the north of the city, where people bring broken things to be mended for free. Carla, how did it start?" },
        { s: "C", t: "It started with a toaster, actually. Mine broke, and the shop told me it would be cheaper to buy a new one. That annoyed me so much that I watched videos, took it apart on the kitchen table and fixed it in an hour. It was only a loose wire. I thought, if I can do this, so can many other people, and that's when I booked a room at the library." },
        { s: "P", t: "Was it busy at the beginning?" },
        { s: "C", t: "Not at all. Four people came, and two of them just wanted tea. But a journalist wrote a short piece, and the following month we had sixty visitors and a queue out of the door." },
        { s: "P", t: "Who does the repairing?" },
        { s: "C", t: "Volunteers, about fifteen of them. Some are retired engineers, some are teenagers who have learnt from their grandparents. I'm not the expert. My job is mainly organising, which means I spend a lot of time making sure nobody takes a screwdriver home by mistake." },
        { s: "P", t: "Do you ever fail to fix something?" },
        { s: "C", t: "Often! About one item in four can't be saved, usually because a part isn't available any more. We don't see it as a defeat, though. The owner learns what went wrong, and we recycle what we can." },
        { s: "P", t: "Shops must hate you." },
        { s: "C", t: "Actually, no. A local electrical store sends customers to us when they can't repair something under guarantee, and in return we send people to them when they need a new part. We have different aims, but we get along." },
        { s: "P", t: "What do you want to do next?" },
        { s: "C", t: "I'd love to teach children. A school nearby has asked us to run a monthly class, where pupils bring a broken toy and try to mend it. I think the confidence they gain is worth more than the toy, so we're planning to start in September." },
      ], items: [
        { n: 24, q: "What gave Carla the idea for the repair café?", options: ["A shop advised her to throw away a broken appliance.", "A friend asked her to teach repair skills.", "She lost her job as an engineer."], a: 0, cue: "it would be cheaper to buy a new one", explain: "The shop told her it would be cheaper to buy a new toaster, which annoyed her enough to repair it herself." },
        { n: 25, q: "What happened at the first event?", options: ["Nobody attended.", "Few people came, but numbers grew quickly.", "Too many people came for the room."], a: 1, cue: "the following month we had sixty visitors", explain: "Only four people came at first, but sixty visited the following month after a news article." },
        { n: 26, q: "What does Carla say about the volunteers?", options: ["They are all retired professionals.", "They are paid a small fee.", "They include young and old people."], a: 2, cue: "some are teenagers", explain: "Some volunteers are retired engineers and some are teenagers, so ages vary." },
        { n: 27, q: "How does Carla describe her own role?", options: ["She organises the sessions.", "She does the most difficult repairs.", "She trains the volunteers."], a: 0, cue: "My job is mainly organising", explain: "She says she is not the expert and that her job is mainly organising." },
        { n: 28, q: "Why can some items not be repaired?", options: ["The owners lose interest.", "A necessary part cannot be found.", "The volunteers lack the tools."], a: 1, cue: "a part isn't available any more", explain: "About one item in four cannot be saved, usually because a part is no longer available." },
        { n: 29, q: "What is Carla's relationship with local shops?", options: ["They compete for customers.", "They help each other.", "They want her to close."], a: 1, cue: "A local electrical store sends customers to us", explain: "A local store sends customers to the café, and the café sends people to the store for new parts." },
        { n: 30, q: "Why does Carla want to work with schools?", options: ["Schools have offered to pay for repairs.", "Pupils would learn to take things apart safely.", "She believes pupils would gain confidence."], a: 2, cue: "the confidence they gain is worth more than the toy", explain: "She values the confidence pupils gain more than the repaired toy. Money and safety are not mentioned." },
      ] },
    ] },
  ] },
  speaking: { parts: [
    { n: 1, type: "interview", minutes: [2, 3], phases: [
      { q: ["What's your name?", "Where are you from?", "Do you work or are you a student?", "What do you enjoy most about your daily routine?"] },
      { topic: "Free time", q: ["How do you usually spend your weekends?", "Is there a new hobby you would like to try?", "Do you prefer to relax alone or with other people?"], extended: "Tell me about something you have learnt to do in the last few years." },
      { topic: "Technology", q: ["How often do you use apps to learn new things?", "Do you think people spend too much time on their phones?", "What was the last app you downloaded?"], extended: "Tell me about a piece of technology you could not live without." },
    ], models: {
      "Tell me about something you have learnt to do in the last few years.": "A few years ago I learnt to cook properly. I started with simple pasta dishes, but now I can prepare a full meal for ten people. It took patience, and I burnt a lot of food at the beginning, but my friends were kind. What I like most is that cooking helps me relax after a long day.",
      "Tell me about a piece of technology you could not live without.": "I could not live without my phone, mainly because it holds everything I need: maps, messages, my bank, even my dictionary. Of course, I try not to look at it all the time, but when I travel it is really useful, especially when I need to find the right train.",
      "How do you usually spend your weekends?": "It depends on the weather. If it's sunny, I go cycling with friends, and if it rains, I stay at home, read or cook something special.",
      "How often do you use apps to learn new things?": "Almost every day. I use one for languages on the train, and sometimes a short course app when I'm waiting for something. It's easy to fit into a busy day.",
    }, tips: ["Give reasons and examples: \"because …\", \"for example …\".", "For \"Tell me about…\", speak for 20–30 seconds: what, when, who, why.", "If you do not understand, say \"Sorry, could you say that again, please?\""] },
    { n: 2, type: "long-turn", minutes: [3, 4], prompt: "Here are two photographs. They show people doing outdoor activities in cold weather. Compare the photographs and say why you think people choose to do these activities.", options: [{ ic: "🏊", label: "Photo A: a group of swimmers entering a frozen lake" }, { ic: "⛷️", label: "Photo B: a family skiing in the mountains" }], follow: ["Which of these activities would you prefer to try?", "Do you enjoy being outdoors in winter?", "What do people in your country do to keep warm in cold weather?"], models: {
      "Here are two photographs. They show people doing outdoor activities in cold weather. Compare the photographs and say why you think people choose to do these activities.": "In the first photo, a group of swimmers are walking into a frozen lake, wearing only swimming costumes and hats. In the second photo, a family is skiing down a snowy mountain. Both activities take place in cold weather, but the first one looks much more extreme. I think the swimmers do it for the challenge and the feeling of energy afterwards, while the skiers probably want to have fun together as a family and enjoy the beautiful scenery. Personally, I would choose skiing, because it seems more relaxing, although the swimmers must feel a great sense of achievement.",
      "Which of these activities would you prefer to try?": "I would prefer to try skiing, because it looks like a lot of fun and it is a good way to spend time with friends.",
      "Do you enjoy being outdoors in winter?": "Yes, as long as I'm dressed warmly. I like walking in the snow because everything is so quiet and beautiful.",
    }, useful: ["In the first photo … whereas in the second …", "Both photos show … but …", "I think people do this because …", "It looks challenging / relaxing / dangerous."], tips: ["Compare – do not only describe each photo.", "Answer the question that is printed above the photos.", "Talk for about a minute without stopping."] },
    { n: 3, type: "collaborative", minutes: [3, 4], prompt: "A neighbourhood wants to become greener and friendlier. Here are some ideas. Talk together about how each idea could improve life for local people, and then decide which two would be most useful.", options: [{ ic: "🌳", label: "a community garden" }, { ic: "🎬", label: "an open-air cinema" }, { ic: "🚲", label: "a bike-sharing scheme" }, { ic: "🛍️", label: "a monthly street market" }, { ic: "🧰", label: "a tool library" }], partnerLines: ["A community garden could bring neighbours together. What do you think?", "I'm not sure a bike scheme would work in winter.", "Maybe we should choose the ideas that most people could use."], follow: ["Which idea would be most popular with young people?", "Would you be willing to volunteer for a project like this?", "How important is it to know your neighbours?"], models: {
      "A neighbourhood wants to become greener and friendlier. Here are some ideas. Talk together about how each idea could improve life for local people, and then decide which two would be most useful.": "I think a community garden is a great idea because people could grow vegetables and meet each other at the same time. An open-air cinema would also be friendly, although it would only work in summer. What do you think? I agree that a bike scheme would help the environment, but maybe not everyone would use it. So shall we choose the garden and the street market? Both would bring people together and support local producers.",
      "Which idea would be most popular with young people?": "I think the open-air cinema would be the most popular, because young people like to go out with friends and it's much cheaper than a normal cinema.",
      "How important is it to know your neighbours?": "I think it's quite important, because neighbours can help each other in emergencies. In my building we share tools and keys, which makes life easier.",
    }, useful: ["What about …?", "I think … is a good idea because …", "I'm not sure that would work, because …", "Shall we choose … and …?", "I see what you mean, but …"], tips: ["Talk to your partner, not to the examiner.", "Ask questions and react to your partner's ideas.", "Decide together at the end."] },
    { n: 4, type: "discussion", minutes: [3, 4], prompt: "How important is it to learn a foreign language?", follow: ["Do you think apps can teach a language as well as classes?", "What are the benefits of living in a different country for a while?", "Some people say that translation devices will soon make language learning unnecessary. What do you think?", "Why do some people find speaking another language difficult?"], models: {
      "How important is it to learn a foreign language?": "I think it's very important, because it opens many doors. You can travel more easily, find better jobs and understand other cultures much better.",
      "Do you think apps can teach a language as well as classes?": "Apps are great for vocabulary and daily practice, but I think they cannot replace a real teacher, because a teacher can correct your mistakes and talk with you.",
      "Why do some people find speaking another language difficult?": "Many people are afraid of making mistakes, so they stay silent. Also, in some countries students mainly study grammar and rarely have the chance to talk.",
    }, useful: ["In my opinion …", "On the other hand …", "That's true, but …", "For example …"] },
  ] },
});
